#!/bin/bash
fail=0
id contractor >/dev/null 2>&1 || { echo "FAIL: пользователь contractor не существует"; exit 1; }

shadow_pw=$(getent shadow contractor | cut -d: -f2)
case "$shadow_pw" in
  !*|\**) ;;
  *) echo "FAIL: пароль не заблокирован"; fail=1 ;;
esac

expire=$(getent shadow contractor | cut -d: -f8)
if [ "$expire" != "1" ]; then
  echo "FAIL: срок действия учётной записи не равен 1970-01-02 (поле expire=$expire, ожидается 1)"
  fail=1
fi

shell=$(getent passwd contractor | cut -d: -f7)
case "$shell" in
  /usr/sbin/nologin|/bin/false) ;;
  *) echo "FAIL: оболочка не неинтерактивная: $shell"; fail=1 ;;
esac

home=$(getent passwd contractor | cut -d: -f6)
[ -d "$home" ] || { echo "FAIL: домашняя директория $home отсутствует"; fail=1; }

[ -f "$home/.ssh/authorized_keys" ] || echo "WARN: authorized_keys не найден (проверьте, что он не удалялся)"

