#!/bin/bash
set -e
SRC=/etc/app/nodes
OUT=/tmp/duplicates.txt

find "$SRC" -type f -print0 \
  | xargs -0 -r sha256sum \
  | awk '{
      h = substr($0, 1, 64)
      p = substr($0, 67)
      c[h]++
      rec[NR] = h SUBSEP p
    }
    END {
      for (i = 1; i <= NR; i++) {
        split(rec[i], a, SUBSEP)
        if (c[a[1]] > 1) print a[2]
      }
    }' \
  | sort > "$OUT"

