#!/bin/bash
LOG=/var/log/nginx/custom_access.log
OUT=/tmp/error_report.txt

# IP — первое поле; статус — первое поле после закрывающей кавычки запроса.
# Учитываются статусы 4xx и 5xx, кроме 404.
awk -F'"' '
{
    split($1, a, " "); ip = a[1]
    split($3, b, " "); s = b[1]
    if (s ~ /^[45][0-9][0-9]$/ && s != "404") cnt[ip]++
}
END {
    for (i in cnt) print cnt[i], i
}' "$LOG" | sort -k1,1nr -k2,2 > "$OUT"

