owner_grp=$(stat -c %G "$d")
[ "$owner_grp" = "devteam" ] || { echo "FAIL: группа каталога $owner_grp, ожидалась devteam"; fail=1; }
# setgid (2xxx) и sticky (xxx1 в 1xxx)
[ $(( 0$perm / 1000 % 10 & 2 )) -ne 0 ] || { echo "FAIL: нет setgid"; fail=1; }
[ $(( 0$perm / 1000 % 10 & 1 )) -ne 0 ] || { echo "FAIL: нет sticky bit"; fail=1; }
# Группа имеет rwx
[ $(( 0$perm / 10 % 10 & 7 )) -eq 7 ] || { echo "FAIL: у группы нет полных прав (perm=$perm)"; fail=1; }
# ACL по умолчанию для devteam
getfacl -p "$d" 2>/dev/null | grep -q '^default:group:devteam:rwx' || { echo "FAIL: нет default ACL для devteam"; fail=1; }
# Функциональный тест: новый файл и подпапка наследуют группу
